const show=()=>{const m=+members.value,p=+perMember.value,a=Math.min(+affected.value,m),w=+warmup.value,total=m*p,moved=a*p;affected.max=m;if(+affected.value>m)affected.value=m;const barrier=total*w,incremental=moved*w;world.textContent='Group: '+m+' consumers / '+total+' partitions
Affected ownership: '+moved+' partitions

Group-wide barrier exposure: '+barrier+' partition-seconds
Incremental handoff exposure: '+incremental+' partition-seconds
Toy reduction: '+((1-incremental/barrier)*100).toFixed(0)+'%

Unaffected partitions keep working only if clients, broker, assignment, and workload behave as expected.'};[members,perMember,affected,warmup].forEach(e=>e.oninput=show);show();

function drawMechanism(){const m=+members.value,p=+perMember.value,a=Math.min(+affected.value,m),w=+warmup.value;let rows='';for(let c=0;c<m;c++){const box=(paused)=>Array.from({length:p},(_,i)=>'<span class="mark '+(paused?'bad':'good')+'">P'+(c*p+i)+'</span>').join('');rows+='<tr><th>C'+c+(c<a?' · changing':'')+'</th><td>'+box(true)+'</td><td>'+box(c<a)+'</td></tr>';}mechanismView.innerHTML='<p><strong>Orange = waits '+w+' s. Green = continues processing.</strong></p><div style="overflow-x:auto"><table><thead><tr><th>Owner</th><th>Global barrier</th><th>Incremental handoff</th></tr></thead><tbody>'+rows+'</tbody></table></div><p>Count waiting partitions: '+(m*p)+' versus '+(a*p)+'. Multiply both by '+w+' s: <strong>'+(m*p*w)+' versus '+(a*p*w)+' partition-seconds</strong>.</p><p class="note">A comparison of exposure, not measured Kafka behavior. Ownership transfer can still pause the affected work; coordination and warm-up are simplified.</p>';}
const updateVisual=()=>{show();drawMechanism();};[members,perMember,affected,warmup].forEach(e=>e.oninput=updateVisual);updateVisual();

const show=()=>{const n=+leaves.value,k=Math.min(+divergent.value,n),depth=Math.log2(n),tree=2*n-1,upper=Math.min(tree,1+2*k*depth);divergent.max=Math.min(n,64);if(+divergent.value>n)divergent.value=n;world.textContent='Balanced tree depth: '+depth+'
Full value-bucket comparison: '+n+' buckets
Whole tree size: '+tree+' hash nodes
Toy hierarchical upper bound: '+upper+' hash nodes
Reduction versus value buckets: '+Math.max(0,(1-upper/n)*100).toFixed(1)+'%

Hash comparison locates candidate ranges; version semantics decide repair.'};[leaves,divergent].forEach(e=>e.oninput=show);show();

function drawMechanism(){const target=driftLeaf.value||'D',a=['A','B','C','D'],b=a.map(x=>x===target?'X':x),left=a.slice(0,2).join('')===b.slice(0,2).join(''),right=a.slice(2).join('')===b.slice(2).join(''),same=left&&right;const node=(x,y,w,text,ok)=>'<rect x="'+x+'" y="'+y+'" width="'+w+'" height="46" rx="6" fill="'+(ok?'#397852':'#9b5139')+'"/><text x="'+(x+w/2)+'" y="'+(y+28)+'" text-anchor="middle" font-size="15">'+text+'</text>';let svg='<svg viewBox="0 0 400 260" role="img" aria-label="Compare root, then differing half, then leaves"><path d="M200 58 L100 94 M200 58 L300 94 M100 140 L48 184 M100 140 L145 184 M300 140 L252 184 M300 140 L350 184" fill="none" stroke="#adc8ca" stroke-width="2"/>'+node(100,12,200,'ABCD / '+b.join(''),same)+node(8,94,184,'AB / '+b.slice(0,2).join(''),left)+node(208,94,184,'CD / '+b.slice(2).join(''),right);a.forEach((v,i)=>{const skipped=same||(i<2?left:right);svg+=node(3+i*100,184,94,skipped?'skip':v+' / '+b[i],skipped||v===b[i]);});svg+='</svg>';mechanismView.innerHTML='<p><strong>Replica 1 / Replica 2</strong> · green fingerprints match; orange differ.</p>'+svg+'<ol><li>Compare the combined root: '+(same?'match, stop.':'different, open both halves.')+'</li><li>'+(same?'No descendant checks needed.':(left?'AB matches → skip A and B.':'AB differs → check A and B.')+' '+(right?'CD matches → skip C and D.':'CD differs → check C and D.'))+'</li><li>'+(same?'No repair candidate.':'Changed leaf '+target+' contains '+target+' versus X. Decide which version is authoritative separately.')+'</li></ol><p class="note">Letters are collision-free symbolic fingerprints for this miniature example, not cryptographic hashes. Large-tree estimate above is a separate scale model.</p>';}
const updateVisual=()=>{show();drawMechanism();};[leaves,divergent].forEach(e=>e.oninput=updateVisual);driftLeaf.onchange=drawMechanism;updateVisual();

const show=()=>{const p=+newPct.value;const safe=dualWrite.checked||backfilled.checked||oldReaderTolerant.checked;const readable=safe?100:100-p;world.textContent='Synthetic records: 1,000
Touched by new writers: '+(p*10)+'
Old-reader success after rollback: '+readable.toFixed(0)+'%
Rollback verdict: '+(readable===100?'STATE-COMPATIBLE IN THIS TOY':'UNSAFE — '+(p*10)+' records use only the new form')+'

Expand readers first; contract the old form only after rollback targets no longer depend on it.'};[newPct,dualWrite,backfilled,oldReaderTolerant].forEach(e=>e.oninput=show);show();

function drawMechanism(){const p=+newPct.value,kept=dualWrite.checked||backfilled.checked,safe=kept||oldReaderTolerant.checked,ok=1000-(safe?0:p*10);mechanismView.innerHTML='<table><thead><tr><th>Persistent data</th><th>After rollback to old reader</th></tr></thead><tbody><tr><td>'+(1000-p*10)+' untouched records<br><code>full_name: Ada Lovelace</code></td><td>→ full_name found → readable</td></tr><tr><td>'+(p*10)+' changed records<br><code>given_name: Ada<br>family_name: Lovelace<br>full_name: '+(kept?'Ada Lovelace':'MISSING')+'</code></td><td>→ '+(kept?'full_name found':oldReaderTolerant.checked?'tolerant reader joins split fields':'old reader requires missing field')+' → <strong>'+(safe?'readable':'FAILS')+'</strong></td></tr></tbody></table><p><strong>'+ok+' / 1,000 readable</strong> after code rollback</p><div class="band" role="img" aria-label="'+ok+' readable, '+(1000-ok)+' unreadable records"><span class="good" style="width:'+(ok/10)+'%"></span><span class="bad" style="width:'+((1000-ok)/10)+'%"></span></div><p>Green = readable. Orange = incompatible stored data. Binary rollback changes the reader; it leaves these records in place.</p>';}
const updateVisual=()=>{show();drawMechanism();};[newPct,dualWrite,backfilled,oldReaderTolerant].forEach(e=>e.oninput=updateVisual);updateVisual();

const show=()=>{const n=+devCases.value,it=+iterations.value,f=+fixes.value,base=.7,basePass=Math.floor(n*base),devPass=Math.min(n,basePass+it*f),dev=100*devPass/n;const visibleHoldout=peekHoldout.checked?Math.min(100,70+it*f/2):70;world.textContent='Baseline / untouched deployment estimate: 70.0%
Visible development score: '+dev.toFixed(1)+'% ('+devPass+'/'+n+')
Displayed holdout score: '+visibleHoldout.toFixed(1)+'%
Evidence gap versus deployment: '+(visibleHoldout-70).toFixed(1)+' points

'+(peekHoldout.checked?'LEAKAGE: this holdout has become development data. Refresh it.':'Holdout remains untouched in this toy; use it sparingly at a decision gate.')};[devCases,iterations,fixes,peekHoldout].forEach(e=>e.oninput=show);show();

function drawMechanism(){const n=+devCases.value,changes=+iterations.value*+fixes.value,pass=Math.min(n,Math.floor(n*.7)+changes),dev=pass/n*100,h=peekHoldout.checked?Math.min(100,70+changes/2):70;const bar=(label,pct,extra)=>'<p>'+label+': <strong>'+pct.toFixed(1)+'%</strong> '+extra+'</p><div class="band" role="img" aria-label="'+label+' '+pct.toFixed(1)+' percent"><span class="good" style="width:'+pct+'%"></span><span class="bad" style="width:'+(100-pct)+'%"></span></div>';mechanismView.innerHTML='<div class="arrowpath">Development failures → '+iterations.value+' rounds of targeted fixes → updated prompt</div><div class="arrowpath">'+(peekHoldout.checked?'HOLDOUT failures → also fed into fixes → holdout is now development data':'Holdout cases → evaluation only · no feedback into prompt tuning')+'</div>'+bar('Development',dev,'('+pass+'/'+n+' cases)')+bar('Displayed holdout',h,peekHoldout.checked?'(contaminated score)':'(140/200 cases)')+bar('Untouched-case assumption',70,'(fixed in this toy)')+'<p>All bars: 0% at left, 100% at right. Green = pass, orange = fail. A higher contaminated bar does not move the untouched-case bar.</p><p class="note">The fixed 70% assumption isolates memorization. Real improvements may generalize; measure that with independent evidence. This diagram is not an estimate of your production quality.</p>';}
const updateVisual=()=>{show();drawMechanism();};[devCases,iterations,fixes,peekHoldout].forEach(e=>e.oninput=updateVisual);updateVisual();

const show=()=>{const a=+f1.value,b=+f2.value,x=+p1.value,y=+p2.value,e=+eta.value,f=Math.abs(a-b),micro=e*x*y*1000;const inRange=f>=1&&f<=11;world.textContent='Difference frequency: '+f.toFixed(1)+' THz
Toy output: '+micro.toFixed(1)+' μW
Paper's demonstrated tuning range: 1–11 THz
Range check: '+(inRange?'WITHIN REPORTED RANGE':'OUTSIDE REPORTED RANGE')+'

Constant efficiency is a teaching simplification, not a device prediction.'};[f1,f2,p1,p2,eta].forEach(e=>e.oninput=show);show();

function drawMechanism(){const a=+f1.value,b=+f2.value,f=Math.abs(a-b),x=30+8*a,y=30+8*b,out=30+8*f,power=+eta.value*+p1.value*+p2.value*1000;let ticks='';for(let i=0;i<=40;i+=10)ticks+='<text x="'+(30+8*i)+'" y="153" text-anchor="middle" font-size="14">'+i+'</text><text x="'+(30+8*i)+'" y="291" text-anchor="middle" font-size="14">'+i+'</text>';mechanismView.innerHTML='<svg viewBox="0 0 390 325" role="img" aria-label="Pump gap '+f.toFixed(1)+' terahertz becomes difference frequency"><text x="15" y="24" font-size="17">Inputs: same frequency ruler (THz)</text><path d="M30 130 H350 M30 267 H350" stroke="#adc8ca" stroke-width="2"/><path d="M'+x+' 57 V130 M'+y+' 86 V130" stroke="#ffd08a" stroke-width="3"/><text x="'+Math.min(x,330)+'" y="48" text-anchor="end" font-size="16">P1 '+a+'</text><text x="'+Math.max(y,65)+'" y="79" text-anchor="end" font-size="16">P2 '+b+'</text><path d="M'+Math.min(x,y)+' 110 H'+Math.max(x,y)+'" stroke="#ffd08a" stroke-width="8"/><text x="15" y="187" font-size="17">Gap |'+a+' − '+b+'| = '+f.toFixed(1)+' THz</text><rect x="38" y="221" width="80" height="46" fill="#397852"/><text x="15" y="212" font-size="15">Green: reported 1–11 THz window</text><path d="M'+out+' 220 V267" stroke="#ffd08a" stroke-width="4"/>'+ticks+'<text x="15" y="318" font-size="15">Orange output marker: '+f.toFixed(1)+' THz</text></svg><p>Separate power arithmetic: '+eta.value+' mW/W² × '+p1.value+' W × '+p2.value+' W = <strong>'+power.toFixed(1)+' μW</strong>.</p><p class="note">Frequency positions use a common scale. Power is a separate illustrative formula, not a measured conversion curve or a device simulation.</p>';}
const updateVisual=()=>{show();drawMechanism();};[f1,f2,p1,p2,eta].forEach(e=>e.oninput=updateVisual);updateVisual();
